import re

def gitignore_to_regex(pattern):
    pattern = pattern.rstrip('\r\n')
    if not pattern or pattern.startswith('#'):
        return None
    negated = pattern.startswith('!')
    if negated:
        pattern = pattern[1:]
    dir_only = pattern.endswith('/')
    if dir_only:
        pattern = pattern[:-1]

    anchored = False
    if pattern.startswith('/'):
        anchored = True
        pattern = pattern[1:]
    elif '/' in pattern:
        anchored = True

    i, n = 0, len(pattern)
    res = []
    while i < n:
        c = pattern[i]
        if c == '*':
            if i + 1 < n and pattern[i+1] == '*':
                if i + 2 < n and pattern[i+2] == '/':
                    res.append('(?:.*/)?')
                    i += 3
                    continue
                else:
                    res.append('.*')
                    i += 2
                    continue
            else:
                res.append('[^/]*')
                i += 1
        elif c == '?':
            res.append('[^/]')
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j >= n:
                res.append(re.escape(c))
                i += 1
            else:
                stuff = pattern[i+1:j].replace('\\\\', '\\')
                i = j + 1
                if stuff.startswith('!'):
                    stuff = '^' + stuff[1:]
                elif stuff.startswith('^'):
                    stuff = '\\\\' + stuff
                res.append('[' + stuff + ']')
        elif c == '\\':
            if i + 1 < n:
                res.append(re.escape(pattern[i+1]))
                i += 2
            else:
                res.append('\\\\')
                i += 1
        else:
            res.append(re.escape(c))
            i += 1

    regex_str = ''.join(res)
    if anchored:
        regex_str = '^' + regex_str + ('(?:$|/)' if dir_only else '(?:$|/)')
    else:
        regex_str = '(?:^|/)' + regex_str + ('(?:$|/)' if dir_only else '(?:$|/)')

    return (re.compile(regex_str), negated, dir_only)

print(gitignore_to_regex('*.py'))
print(gitignore_to_regex('/build/'))
print(gitignore_to_regex('foo/bar'))
""}

