        num_color = self.opts.color_line_number if self.opts.color else None

        if self.opts.only_matching:
            for lnum, line_clean, m_iter in line_matches:
                for m in m_iter:
                    start, end = m.span()
                    matched_bytes = line_clean[start:end]
                    if self.opts.color:
                        matched_bytes = colorize(matched_bytes, match_color)
                    prefix = b''
                    if self.opts.numbers:
                        prefix += colorize(str(lnum).encode('ascii'), num_color) + b':'
                    sys.stdout.buffer.write(prefix + matched_bytes + b'\n')
            return

        for lnum, line_clean, m_iter in line_matches:
            line_hl = highlight_matches(line_clean, self.regex, match_color)
            prefix = b''
            if self.opts.numbers:
                prefix += colorize(str(lnum).encode('ascii'), num_color) + b':'
            sys.stdout.buffer.write(prefix + line_hl + b'\n')

    def print_stats(self, duration):
        sys.stdout.write(f"{self.matches_count} matches\n")
        sys.stdout.write(f"{self.files_matched_count} files contained matches\n")
        sys.stdout.write(f"{self.files_searched_count} files searched\n")
        sys.stdout.write(f"{self.bytes_searched_count} bytes searched\n")
        sys.stdout.write(f"{duration:.6f} seconds\n")

def main():
    opts = parse_args(sys.argv)
    searcher = Searcher(opts)
    success = searcher.search_all()
    sys.exit(0 if success else 1)

